'use strict';

var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var dgemm = require( '@stdlib/blas/base/dgemm' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var dgemmsw = require( './../lib' );

var opts = {
	'dtype': 'float64'
};

// Use dimensions which exceed the recursion cutoff, such that the Strassen–Winograd algorithm is used:
var M = 300;
var N = 300;
var K = 300;

var A = discreteUniform( M*K, 0, 10, opts ); // 300x300
var B = discreteUniform( K*N, 0, 10, opts ); // 300x300
var C = discreteUniform( M*N, 0, 10, opts ); // 300x300

// Compute a reference result using the conventional algorithm:
var expected = dgemm( 'row-major', 'no-transpose', 'no-transpose', M, N, K, 1.0, A, K, B, N, 1.0, new Float64Array( C ), N );

// Compute the same result using the Strassen–Winograd algorithm:
var out1 = dgemmsw( 'row-major', 'no-transpose', 'no-transpose', M, N, K, 1.0, A, K, B, N, 1.0, new Float64Array( C ), N );
var out2 = dgemmsw.ndarray( 'no-transpose', 'no-transpose', M, N, K, 1.0, A, K, 1, 0, B, N, 1, 0, 1.0, new Float64Array( C ), N, 1, 0 );

// For small integer-valued inputs, every intermediate result is exactly representable, and, thus, both algorithms return the exact result:
var d1 = 0.0;
var d2 = 0.0;
var i;
for ( i = 0; i < expected.length; i++ ) {
	d1 = max( d1, abs( out1[ i ]-expected[ i ] ) );
	d2 = max( d2, abs( out2[ i ]-expected[ i ] ) );
}
console.log( 'Maximum absolute difference from the conventional algorithm (BLAS interface): %d', d1 );
console.log( 'Maximum absolute difference from the conventional algorithm (ndarray interface): %d', d2 );
